/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.util.Optional;

import javax.sql.DataSource;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.RequestScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenLookupGateway;

/**
 * JDBC adapter for token lookup during introspection.
 *
 * Responsibilities: - Query {@code _oauth_session} by JTI to resolve JWT tokens. - Return empty for
 * opaque tokens (not yet supported via raw token lookup).
 *
 * Design notes: - Only non-expired sessions are returned ({@code expiration > NOW()}). - The
 * {@code jti} column must be indexed for efficient lookups (added in task 01-05). - Opaque token
 * lookup is a no-op placeholder for future support.
 */
@RequestScoped
@RequiredArgsConstructor
public class TokenLookupSqlAdapter implements TokenLookupGateway {

  /**
   * Data source used for JDBC operations.
   */
  private final DataSource source;

  /**
   * JSON mapper used to deserialize authentication data.
   */
  private final ObjectMapper mapper;

  /**
   * Looks up an active session by its JWT ID.
   *
   * Queries {@code _oauth_session} for a non-expired row whose {@code jti} matches. Deserializes
   * the stored {@code auth_data} JSON to extract subject and scope.
   *
   * @param tenantSlug tenant identifier (reserved for future multi-tenant filtering)
   * @param jti JWT ID claim value
   * @return optional active introspection result
   */
  @Override
  public Optional<TokenIntrospectionResult> lookupByJti(String tenantSlug, String jti) {
    try (Connection conn = source.getConnection();
        PreparedStatement stmt = conn.prepareStatement(
            "SELECT t.jti, t.client_id as token_client_id, t.scope as token_scope, t.auth_data as token_auth_data, s.expiration, s.client_id, s.auth_data FROM _oauth_session_token t JOIN _oauth_session s ON s.session = t.session WHERE t.jti = ? AND t.revoked_at IS NULL AND t.expires_at > ? AND s.expiration > ?")) {
      stmt.setString(1, jti);
      stmt.setTimestamp(2, new Timestamp(System.currentTimeMillis()));
      stmt.setTimestamp(3, new Timestamp(System.currentTimeMillis()));
      try (ResultSet rs = stmt.executeQuery()) {
        if (rs.next()) {
          String authJson = rs.getString("token_auth_data");
          if (authJson == null || authJson.isBlank()) {
            authJson = rs.getString("auth_data");
          }
          AuthenticationData auth = mapper.readValue(authJson, AuthenticationData.class);
          long expEpoch = rs.getTimestamp("expiration").toInstant().getEpochSecond();
          String scopeStr = rs.getString("token_scope");
          if (scopeStr == null) {
            scopeStr = auth.getScopes() == null ? "" : String.join(" ", auth.getScopes());
          }
          String clientId = rs.getString("token_client_id");
          if (clientId == null || clientId.isBlank()) {
            clientId = rs.getString("client_id");
          }
          return Optional.of(TokenIntrospectionResult.builder().active(true).sub(auth.getUsername())
              .clientId(clientId).scope(scopeStr).exp(expEpoch).jti(jti).build());
        }
      }
    } catch (SQLException | JsonProcessingException ex) {
      throw new IllegalStateException(ex);
    }
    return Optional.empty();
  }

  /**
   * Looks up an active session by its raw (opaque) token value.
   *
   * Opaque token lookup is not yet supported. Always returns empty.
   *
   * @param tenantSlug tenant identifier
   * @param rawToken opaque token string
   * @return empty optional
   */
  @Override
  public Optional<TokenIntrospectionResult> lookupByRawToken(String tenantSlug, String rawToken) {
    return Optional.empty();
  }
}
